 10	using CommunityToolkit.Mvvm.ComponentModel;
 11	using CommunityToolkit.Mvvm.Input;
 12	using LoadOrderKeeper.Models;
 13	using LoadOrderKeeper.Services;
 14	using LoadOrderKeeper.ViewTexts;
 15	
 16	namespace LoadOrderKeeper.ViewModels
 17	{
 18	    public class ConfirmationRequestedEventArgs : EventArgs
 19	    {
 20	        public string Title { get; }
 21	        public string Message { get; }
 22	        public ConfirmationIcon Icon { get; }
 23	        public ConfirmationButton Buttons { get; }
 24	        public ConfirmationResult Result { get; set; }
 25	
 26	        public ConfirmationRequestedEventArgs(string title, string message, ConfirmationIcon icon = ConfirmationIcon.Warning, ConfirmationButton buttons = ConfirmationButton.YesNo)
 27	        {
 28	            Title = title;
 29	            Message = message;
 30	            Icon = icon;
 31	            Buttons = buttons;
 32	            Result = ConfirmationResult.None;
 33	        }
 34	    }
 35	
 36	    public partial class DiffDialogViewModel : ObservableObject, IDisposable
 37	    {
 38	        private readonly MainViewModel _mainViewModel;
 39	        private readonly ListCollectionView _filteredDiffLines;
 40	        private bool _suppressCollectionNotification;
 41	        private string _lastDiffSignature = string.Empty;
 42	        private bool _isRefreshing;
 43	
 44	        [ObservableProperty]
 45	        private bool _isConfigValid = true;
 46	
 47	        [ObservableProperty]
 48	        private bool _isOperationInProgress;
 49	
 50	        [ObservableProperty]
 51	        private bool _showAllMods = false;
 52	
 53	        public bool ShowOverlay => !IsConfigValid && !IsOperationInProgress;
 54	
 55	        // Add localization texts
 56	        public DiffDialogTexts Texts { get; } = new();
 57	        public MenuViewModel Menu => _mainViewModel.Menu;
 58	
 59	        public DiffDialogViewModel(IEnumerable<DiffLineModel> trimmedLines, IEnumerable<DiffLineModel> fullLines, MainViewModel mainViewModel)
 60	        {
 61	            _mainViewModel = mainViewModel;
 62	            var trimmedList = trimmedLines.ToList();
 63	            DiffLines = new ObservableCollection<DiffLineModel>(fullLines);
 64	            _filteredDiffLines = new ListCollectionView(DiffLines);
 65	            _filteredDiffLines.Filter = FilterDiffLines;
 66	            DiffLines.CollectionChanged += OnDiffCollectionChanged;
 67	            UpdateReferenceCommand = new AsyncRelayCommand(UpdateReferenceWithConfirmationAsync, CanUpdateReference);
 68	            FixLoadOrderCommand = _mainViewModel.FixLoadOrderCommand;
 69	            ReEnableModCommand = new AsyncRelayCommand<DiffLineModel>(ReEnableModAsync);
 70	            RemoveNewModCommand = new AsyncRelayCommand<DiffLineModel>(RemoveNewModAsync);
 71	            ReplaceRemovedModCommand = new AsyncRelayCommand<(DiffLineModel Removed, DiffLineModel Replacement)>(ReplaceRemovedModAsync);
 72	            ToggleDependentChangesCommand = new RelayCommand<DiffLineModel>(ToggleDependentChanges);
 73	            _mainViewModel.PropertyChanged += OnMainViewModelPropertyChanged;
 74	            
 75	            // Subscribe to configuration validation changes
 76	            var configCoordinator = _mainViewModel.GetConfigurationCoordinator();
 77	            IsConfigValid = configCoordinator.IsConfigValid;
 78	            configCoordinator.ValidationChanged += OnConfigValidationChanged;
 79	            
 80	            // Subscribe to file monitoring coordinator's change detected event
 81	            var coordinator = _mainViewModel.GetFileMonitoringCoordinator();
 82	            coordinator.ChangeDetected += OnFileChangeDetected;
 83	            
 84	            ApplyLineNumbers(DiffLines);
 85	            UpdateDiffState();
 86	            _lastDiffSignature = BuildSignature(trimmedList);
 87	            DiffStatusMessage = Texts.DifferencesLoadedStatus;
 88	        }
 89	
 90	        /// <summary>
 91	        /// Test-only constructor. Accepts a pre-populated diff collection and skips all
 92	        /// coordinator subscriptions that require a full <see cref="MainViewModel"/> dependency
 93	        /// graph. Not for production use.
 94	        /// </summary>
 95	        [System.ComponentModel.EditorBrowsable(System.ComponentModel.EditorBrowsableState.Never)]
 96	        internal DiffDialogViewModel(ObservableCollection<DiffLineModel> diffLines)
 97	        {
 98	            _mainViewModel = null!;
 99	            DiffLines = diffLines;
100	            _filteredDiffLines = new ListCollectionView(DiffLines);
101	            _filteredDiffLines.Filter = FilterDiffLines;
102	            DiffLines.CollectionChanged += OnDiffCollectionChanged;
103	            UpdateReferenceCommand = new AsyncRelayCommand(() => Task.CompletedTask);
104	            FixLoadOrderCommand = new AsyncRelayCommand(() => Task.CompletedTask);
105	            ReEnableModCommand = new AsyncRelayCommand<DiffLineModel>(_ => Task.CompletedTask);
106	            RemoveNewModCommand = new AsyncRelayCommand<DiffLineModel>(_ => Task.CompletedTask);
107	            ReplaceRemovedModCommand = new AsyncRelayCommand<(DiffLineModel Removed, DiffLineModel Replacement)>(_ => Task.CompletedTask);
108	            ToggleDependentChangesCommand = new RelayCommand<DiffLineModel>(ToggleDependentChanges);
109	            ApplyLineNumbers(DiffLines);
110	            UpdateDiffState();
111	        }
112	
113	        public ObservableCollection<DiffLineModel> DiffLines { get; }
114	
115	        public ICollectionView FilteredDiffLines => _filteredDiffLines;
116	
117	        public string Title => Texts.WindowTitle;
118	
119	        public string Description => Texts.DescriptionText;
120	
121	        public string ShowAllModsToggleText => Texts.ShowAllModsToggleText;
122	
123	        public string UpdateReferenceButtonText
124	        {
125	            get
126	            {
127	                // Add ellipsis if confirmation dialog will be shown
128	                bool needsConfirmation = DiffLines.Any(line => line.ChangeType == DiffChangeType.Removed || line.ChangeType == DiffChangeType.Inserted);
129	                string baseText = Texts.AcceptChangesButtonText;
130	                return needsConfirmation ? $"{baseText}..." : baseText;
131	            }
132	        }
133	
134	        public string FixLoadOrderButtonText => Texts.FixLoadOrderButtonText;
135	
136	        public string DiscardChangesButtonText => Texts.DiscardChangesButtonText;
137	
138	        public string CloseButtonText => Texts.CloseButtonText;
139	
140	        public string NoDifferencesMessage => Texts.NoDifferencesMessage;
141	
142	        public string ReEnableModMenuText => Texts.ReEnableModMenuText;
143	
144	        public string ReplaceWithMenuText => Texts.ReplaceWithMenuText;
145	
146	        public string RemoveModMenuText => Texts.RemoveModMenuText;
147	
148	        public string FileMenuHeader => Menu.FileMenuHeader;
149	        
150	        public string OpenPluginsMenuText => Menu.OpenPluginsMenuText;

151	        
152	        public string OpenReferenceMenuText => Menu.OpenReferenceMenuText;
153	        
154	        public string OpenAppDataFolderMenuText => Menu.OpenAppDataFolderMenuText;
155	        
156	        public string OpenGameFolderMenuText => Menu.OpenGameFolderMenuText;
157	
158	        public string ExitMenuText => Menu.ExitMenuText;
159	
160	        public string EditMenuHeader => Menu.EditMenuHeader;
161	
162	        public IRelayCommand OpenPluginsFileCommand => _mainViewModel.OpenPluginsFileCommand;
163	
164	        public bool ShowSortingRecommendation => HasDifferences && _mainViewModel.SortingRecommendationActive;
165	
166	        public string SortingRecommendationMessage => _mainViewModel.SortingRecommendationMessage;
167	
168	        public IReadOnlyList<DiffLineModel> AddedMods => DiffLines.Where(line => line.ChangeType == DiffChangeType.Added).ToList();
