338	        private int ComputeScrollTargetIndex()
339	        {
340	            if (DiffLines.Count == 0)
341	            {
342	                return -1;
343	            }
344	
345	            if (!ShowAllMods)
346	            {
347	                return HasDifferences ? 0 : -1;
348	            }
349	
350	            if (HasDifferences)

351	            {
352	                for (int index = 0; index < DiffLines.Count; index++)
353	                {
354	                    if (DiffLines[index].ChangeType != DiffChangeType.Unchanged && DiffLines[index].ChangeType != DiffChangeType.Separator)
355	                    {
356	                        return index;
357	                    }
358	                }
359	            }
360	
361	            return DiffLines.Count - 1;
362	        }
