431	        private static string BuildSignature(IEnumerable<DiffLineModel> lines)
432	        {
433	            var builder = new StringBuilder();
434	            foreach (var line in lines)
435	            {
436	                builder.Append((int)line.ChangeType)
437	                       .Append(':')
438	                       .AppendLine(line.Text);
439	            }
440	
441	            return builder.ToString();
442	        }
