459	        public async Task<bool> RefreshDiffAsync(string? reason = null)
460	        {
461	            if (_isRefreshing)
462	            {
463	                return false;
464	            }
465	
466	            _isRefreshing = true;
467	            try
468	            {
469	                var trimmedLines = await DiffService.GetPluginsDiffAsync(_mainViewModel.Config);
470	                string newSignature = BuildSignature(trimmedLines);
471	
472	                bool signatureChanged = !string.Equals(newSignature, _lastDiffSignature, StringComparison.Ordinal);
473	                
474	                if (signatureChanged)
475	                {
476	                    var fullLines = await DiffService.GetFullPluginsDiffAsync(_mainViewModel.Config);
477	                    ReplaceDiffLines(fullLines);
478	                    _lastDiffSignature = newSignature;
479	                    DiffStatusMessage = reason ?? Texts.DifferencesLoadedStatus;
480	                    RequestScroll();
481	                }
482	                else
483	                {
484	                    DiffStatusMessage = Texts.NoNewDifferencesStatus;
485	                }
486	
487	                return signatureChanged;
488	            }
489	            catch (Exception ex)
490	            {
491	                DiffStatusMessage = Texts.FailedToRefreshError + " " + ex.Message;
492	                return false;
493	            }
494	            finally
495	            {
496	                _isRefreshing = false;
497	            }
498	        }
