513	                return;
514	            }
515	
516	            // Request confirmation from the view
517	            var eventArgs = new ConfirmationRequestedEventArgs(
518	                Texts.ConfirmDiscardTitle, 
519	                Texts.ConfirmDiscardMessage,
520	                ConfirmationIcon.Warning,
521	                ConfirmationButton.YesNo);
